import { motion } from 'framer-motion'
import { useInView } from 'framer-motion'
import { useRef } from 'react'

const About: React.FC = () => {
  const ref = useRef(null)
  const isInView = useInView(ref, { once: true, margin: "-100px" })

  const stats = [
    { label: "Years Experience", value: "8+" },
    { label: "Projects Delivered", value: "50+" },
    { label: "Enterprise Clients", value: "25+" },
    { label: "Technologies", value: "20+" }
  ]

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1,
      },
    },
  }

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6,
        ease: [0.25, 0.46, 0.45, 0.94],
      },
    },
  }

  return (
    <div className="h-screen flex items-center justify-center bg-bg px-4" ref={ref}>
      <div className="container mx-auto">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
          {/* Left side - Content */}
          <motion.div
            variants={containerVariants}
            initial="hidden"
            animate={isInView ? "visible" : "hidden"}
          >
            {/* Section heading */}
            <motion.div
              className="mb-8"
              variants={itemVariants}
            >
              <h2 className="text-section font-headline font-bold text-text mb-4">
                About
              </h2>
              <p className="text-xl text-slate">
                Passionate technologist driving digital transformation
              </p>
            </motion.div>

            {/* Bio */}
            <motion.div
              className="mb-8"
              variants={itemVariants}
            >
              <p className="text-slate leading-relaxed mb-4">
                With over 8 years of experience in enterprise technology, I specialize in 
                building scalable solutions that transform business operations. My expertise 
                spans data engineering, machine learning, and digital strategy.
              </p>
              <p className="text-slate leading-relaxed">
                I believe in the power of technology to solve complex business challenges 
                and create lasting value for organizations and their stakeholders.
              </p>
            </motion.div>

            {/* Stats grid */}
            <motion.div
              className="grid grid-cols-2 gap-6 mb-8"
              variants={itemVariants}
            >
              {stats.map((stat, index) => (
                <div key={index} className="text-center">
                  <div className="text-3xl font-bold text-accent1 mb-2">
                    {stat.value}
                  </div>
                  <div className="text-sm text-slate uppercase tracking-wider">
                    {stat.label}
                  </div>
                </div>
              ))}
            </motion.div>

            {/* CV Download */}
            <motion.div
              variants={itemVariants}
            >
              <motion.a
                href="/Sergei_Lerner_CV.pdf"
                download
                className="inline-flex items-center px-6 py-3 bg-gradient-to-r from-accent1 to-accent2 text-bg font-bold rounded-full hover:shadow-lg hover:shadow-accent1/25 transition-all duration-300"
                whileHover={{ scale: 1.05, y: -2 }}
                whileTap={{ scale: 0.95 }}
                data-gtag-event="file_download"
                data-gtag-label="Sergei_Lerner_CV.pdf"
                data-gtag-category="engagement"
              >
                <svg className="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M19 9h-4V3H9v6H5l7 7 7-7zM5 18v2h14v-2H5z"/>
                </svg>
                Download CV
              </motion.a>
            </motion.div>
          </motion.div>

          {/* Right side - Avatar */}
          <motion.div
            className="flex justify-center lg:justify-end"
            initial={{ opacity: 0, scale: 0.8 }}
            animate={isInView ? { opacity: 1, scale: 1 } : {}}
            transition={{ delay: 0.3, duration: 0.8 }}
          >
            <div className="relative">
              {/* Avatar placeholder */}
              <div className="w-64 h-64 md:w-80 md:h-80 rounded-full bg-gradient-to-br from-accent1/20 to-accent2/20 border-2 border-accent1/30 flex items-center justify-center">
                <div className="text-center">
                  <div className="text-6xl md:text-8xl font-bold text-accent1 mb-4">
                    SL
                  </div>
                  <div className="text-slate text-lg">
                    Sergei Lerner
                  </div>
                </div>
              </div>
              
              {/* Floating elements around avatar */}
              {[...Array(4)].map((_, i) => (
                <motion.div
                  key={i}
                  className="absolute w-3 h-3 bg-accent1 rounded-full"
                  style={{
                    left: `${50 + Math.cos(i * Math.PI / 2) * 120}%`,
                    top: `${50 + Math.sin(i * Math.PI / 2) * 120}%`,
                  }}
                  animate={{
                    scale: [0.5, 1, 0.5],
                    opacity: [0.3, 1, 0.3],
                  }}
                  transition={{
                    duration: 3,
                    repeat: Infinity,
                    delay: i * 0.5,
                    ease: "easeInOut"
                  }}
                />
              ))}
            </div>
          </motion.div>
        </div>
      </div>
    </div>
  )
}

export default About
