import { motion } from 'framer-motion'
import { useInView } from 'framer-motion'
import { useRef, useState } from 'react'

const Work: React.FC = () => {
  const ref = useRef(null)
  const isInView = useInView(ref, { once: true, margin: "-100px" })
  const [activeIndex, setActiveIndex] = useState(0)

  const projects = [
    {
      title: "Enterprise Data Platform",
      description: "Scalable data infrastructure processing millions of records daily with real-time analytics.",
      image: "https://via.placeholder.com/800x400/0B111A/89F0FF?text=Data+Platform",
      category: "Data Engineering",
      year: "2024"
    },
    {
      title: "AI-Powered Analytics Suite",
      description: "Machine learning platform providing predictive insights for business intelligence.",
      image: "https://via.placeholder.com/800x400/0B111A/3BE4CF?text=AI+Analytics",
      category: "Machine Learning",
      year: "2023"
    },
    {
      title: "Digital Transformation Hub",
      description: "Comprehensive platform for enterprise modernization and process optimization.",
      image: "https://via.placeholder.com/800x400/0B111A/8BA0B2?text=Digital+Hub",
      category: "Digital Strategy",
      year: "2023"
    }
  ]

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1,
      },
    },
  }

  const itemVariants = {
    hidden: { opacity: 0, y: 30 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.6,
        ease: [0.25, 0.46, 0.45, 0.94],
      },
    },
  }

  return (
    <div className="h-screen flex items-center justify-center bg-bg px-4" ref={ref}>
      <div className="container mx-auto">
        {/* Section heading */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, x: -30 }}
          animate={isInView ? { opacity: 1, x: 0 } : {}}
          transition={{ duration: 0.6 }}
        >
          <h2 className="text-section font-headline font-bold text-text mb-4">
            Work
          </h2>
          <p className="text-xl text-slate max-w-2xl mx-auto">
            Selected projects showcasing innovation and technical excellence
          </p>
        </motion.div>

        {/* Project showcase */}
        <motion.div
          className="max-w-6xl mx-auto"
          variants={containerVariants}
          initial="hidden"
          animate={isInView ? "visible" : "hidden"}
        >
          {/* Main project display */}
          <motion.div
            className="relative mb-8"
            variants={itemVariants}
          >
            <div className="relative overflow-hidden rounded-2xl bg-panel/30 border border-panel/20">
              <img
                src={projects[activeIndex].image}
                alt={projects[activeIndex].title}
                className="w-full h-64 md:h-80 object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-bg/80 via-bg/20 to-transparent" />
              
              {/* Project info overlay */}
              <div className="absolute bottom-0 left-0 right-0 p-8">
                <div className="flex items-center justify-between mb-4">
                  <span className="text-accent1 text-sm font-medium tracking-wider uppercase">
                    {projects[activeIndex].category}
                  </span>
                  <span className="text-slate text-sm">
                    {projects[activeIndex].year}
                  </span>
                </div>
                <h3 className="text-2xl md:text-3xl font-bold text-text mb-3">
                  {projects[activeIndex].title}
                </h3>
                <p className="text-slate max-w-2xl">
                  {projects[activeIndex].description}
                </p>
              </div>
            </div>
          </motion.div>

          {/* Project navigation */}
          <motion.div
            className="flex flex-wrap gap-4 justify-center"
            variants={itemVariants}
          >
            {projects.map((project, index) => (
              <motion.button
                key={index}
                onClick={() => setActiveIndex(index)}
                className={`px-6 py-3 rounded-full border transition-all duration-300 ${
                  activeIndex === index
                    ? 'border-accent1 bg-accent1/10 text-accent1'
                    : 'border-panel/30 text-slate hover:border-accent1/50 hover:text-accent1'
                }`}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                {project.title}
              </motion.button>
            ))}
          </motion.div>

          {/* CTA */}
          <motion.div
            className="text-center mt-12"
            variants={itemVariants}
          >
            <motion.button
              className="px-8 py-4 bg-gradient-to-r from-accent1 to-accent2 text-bg font-bold rounded-full hover:shadow-lg hover:shadow-accent1/25 transition-all duration-300"
              whileHover={{ scale: 1.05, y: -2 }}
              whileTap={{ scale: 0.95 }}
              data-gtag-event="project_view"
              data-gtag-label={projects[activeIndex].title}
            >
              View Full Case Study
            </motion.button>
          </motion.div>
        </motion.div>
      </div>
    </div>
  )
}

export default Work
