import { useEffect } from 'react'
import Hero from './components/Hero'
import Services from './components/Services'
import Work from './components/Work'
import About from './components/About'
import Contact from './components/Contact'
import Footer from './components/Footer'
import RightProgress from './components/RightProgress'
import Nav from './components/Nav'
import { useScrollProgress } from './hooks/useScrollProgress'

function App() {
  const scrollProgress = useScrollProgress()

  useEffect(() => {
    // Initialize GA tracking
    if (typeof window !== 'undefined' && window.gtag) {
      window.gtag('event', 'page_view', {
        page_title: 'Portfolio Home',
        page_location: window.location.href,
      })
    }
  }, [])

  return (
    <div className="relative min-h-screen bg-bg">
      {/* Grain overlay */}
      <div className="grain-overlay" />
      
      {/* Navigation */}
      <Nav />
      
      {/* Right progress bar */}
      <RightProgress progress={scrollProgress} />
      
      {/* Main content with scroll snapping */}
      <main className="scroll-snap-container">
        <section className="scroll-snap-section h-screen">
          <Hero />
        </section>
        
        <section className="scroll-snap-section h-screen">
          <Services />
        </section>
        
        <section className="scroll-snap-section h-screen">
          <Work />
        </section>
        
        <section className="scroll-snap-section h-screen">
          <About />
        </section>
        
        <section className="scroll-snap-section h-screen">
          <Contact />
        </section>
      </main>
      
      {/* Footer */}
      <Footer />
    </div>
  )
}

export default App
