import { motion } from 'framer-motion'

interface RightProgressProps {
  progress: number
}

const RightProgress: React.FC<RightProgressProps> = ({ progress }) => {
  return (
    <motion.div
      className="fixed right-6 top-1/2 transform -translate-y-1/2 z-40 hidden lg:block"
      initial={{ opacity: 0, x: 20 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ delay: 1, duration: 0.6 }}
    >
      <div className="relative w-0.5 h-32 bg-panel">
        {/* Progress fill */}
        <motion.div
          className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-accent1 to-accent2"
          style={{ height: `${progress * 100}%` }}
          initial={{ height: 0 }}
          animate={{ height: `${progress * 100}%` }}
          transition={{ duration: 0.1 }}
        />
        
        {/* Glow effect */}
        <div className="absolute bottom-0 left-0 w-full h-full bg-gradient-to-t from-accent1/20 to-transparent" />
      </div>
    </motion.div>
  )
}

export default RightProgress
