import { useEffect, useRef } from 'react'
import { motion } from 'framer-motion'

const Glyph8: React.FC = () => {
  const pathRef = useRef<SVGPathElement>(null)

  useEffect(() => {
    if (!pathRef.current) return

    const path = pathRef.current
    const length = path.getTotalLength()
    
    // Set initial state
    path.style.strokeDasharray = length.toString()
    path.style.strokeDashoffset = length.toString()
    
    // Animate drawing
    const animate = () => {
      path.style.strokeDashoffset = '0'
      path.style.transition = 'stroke-dashoffset 2s ease-in-out'
      
      // Reset after animation
      setTimeout(() => {
        path.style.strokeDashoffset = length.toString()
        path.style.transition = 'none'
      }, 2000)
    }
    
    // Start animation loop
    const interval = setInterval(animate, 6000)
    animate() // Initial animation
    
    return () => clearInterval(interval)
  }, [])

  return (
    <motion.div
      className="relative w-32 h-32 md:w-48 md:h-48"
      animate={{ 
        y: [0, -10, 0],
        rotate: [0, 5, -5, 0]
      }}
      transition={{
        duration: 6,
        repeat: Infinity,
        ease: "easeInOut"
      }}
    >
      <svg
        viewBox="0 0 100 100"
        className="w-full h-full"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        {/* Background glow */}
        <circle
          cx="50"
          cy="50"
          r="45"
          className="fill-accent1/10"
          filter="url(#glow)"
        />
        
        {/* Main 8 shape */}
        <path
          ref={pathRef}
          d="M30 20 Q50 10 70 20 Q80 30 80 40 Q80 50 70 60 Q50 70 30 60 Q20 50 20 40 Q20 30 30 20 M30 40 Q50 30 70 40 Q80 50 80 60 Q80 70 70 80 Q50 90 30 80 Q20 70 20 60 Q20 50 30 40"
          stroke="url(#gradient)"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          className="drop-shadow-[0_0_20px_rgba(137,240,255,0.8)]"
        />
        
        {/* Inner accent line */}
        <path
          d="M35 35 Q50 25 65 35 M35 65 Q50 75 65 65"
          stroke="url(#gradient2)"
          strokeWidth="1"
          strokeLinecap="round"
          opacity="0.6"
        />
        
        {/* Filters and gradients */}
        <defs>
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
            <feMerge> 
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
          
          <linearGradient id="gradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#89F0FF" />
            <stop offset="50%" stopColor="#3BE4CF" />
            <stop offset="100%" stopColor="#89F0FF" />
          </linearGradient>
          
          <linearGradient id="gradient2" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#3BE4CF" />
            <stop offset="100%" stopColor="#89F0FF" />
          </linearGradient>
        </defs>
      </svg>
      
      {/* Floating particles around the glyph */}
      {[...Array(6)].map((_, i) => (
        <motion.div
          key={i}
          className="absolute w-1 h-1 bg-accent1 rounded-full"
          style={{
            left: `${50 + Math.cos(i * Math.PI / 3) * 60}%`,
            top: `${50 + Math.sin(i * Math.PI / 3) * 60}%`,
          }}
          animate={{
            scale: [0, 1, 0],
            opacity: [0, 0.8, 0],
          }}
          transition={{
            duration: 3,
            repeat: Infinity,
            delay: i * 0.5,
            ease: "easeInOut"
          }}
        />
      ))}
    </motion.div>
  )
}

export default Glyph8
