import { motion } from 'framer-motion'

const Footer: React.FC = () => {
  const currentYear = new Date().getFullYear()

  return (
    <footer className="bg-panel/30 border-t border-panel/20 py-8 px-4">
      <div className="container mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-center space-y-4 md:space-y-0">
          {/* Left side - Cookie notice */}
          <motion.div
            className="text-sm text-slate"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
          >
            This site uses cookies to enhance your experience. By continuing to browse, you agree to our use of cookies.
          </motion.div>
          
          {/* Right side - Copyright and privacy */}
          <motion.div
            className="flex flex-col md:flex-row items-center space-y-2 md:space-y-0 md:space-x-6 text-sm text-slate"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            <span>© {currentYear} Sergei Lerner. All rights reserved.</span>
            <a
              href="#privacy"
              className="hover:text-accent1 transition-colors duration-300"
            >
              Privacy Policy
            </a>
          </motion.div>
        </div>
      </div>
    </footer>
  )
}

export default Footer
