import { useEffect, useRef, useState } from 'react'
import * as THREE from 'three'

interface CanvasStreaksProps {
  className?: string
}

const CanvasStreaks: React.FC<CanvasStreaksProps> = ({ className = '' }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [useCanvas, setUseCanvas] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    // Check if Three.js should be disabled
    const useCanvasFlag = (import.meta as any).env?.VITE_USE_CANVAS !== '0'
    if (!useCanvasFlag) {
      setUseCanvas(false)
      return
    }

    if (!canvasRef.current) return

    let animationId: number
    let scene: THREE.Scene
    let camera: THREE.PerspectiveCamera
    let renderer: THREE.WebGLRenderer
    let streaks: THREE.Group

    try {
      // Scene setup
      scene = new THREE.Scene()
      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000)
      renderer = new THREE.WebGLRenderer({ 
        canvas: canvasRef.current, 
        alpha: true,
        antialias: true 
      })
      
      renderer.setSize(window.innerWidth, window.innerHeight)
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))

      // Create light streaks
      streaks = new THREE.Group()
      
      for (let i = 0; i < 15; i++) {
        const geometry = new THREE.BufferGeometry()
        const points = []
        
        // Create diagonal line from top-left to bottom-right
        const startX = (Math.random() - 0.5) * 4
        const startY = (Math.random() - 0.5) * 4
        const endX = startX + (Math.random() - 0.5) * 2 + 2
        const endY = startY - (Math.random() - 0.5) * 2 - 2
        
        points.push(new THREE.Vector3(startX, startY, 0))
        points.push(new THREE.Vector3(endX, endY, 0))
        
        geometry.setFromPoints(points)
        
        const material = new THREE.LineBasicMaterial({
          color: new THREE.Color(0x89F0FF),
          transparent: true,
          opacity: Math.random() * 0.5 + 0.2,
        })
        
        const line = new THREE.Line(geometry, material)
        line.position.z = Math.random() * 10 - 5
        line.userData = { speed: Math.random() * 0.02 + 0.01 }
        
        streaks.add(line)
      }

      // Add star particles
      const starGeometry = new THREE.BufferGeometry()
      const starPositions = []
      const starColors = []
      
      for (let i = 0; i < 100; i++) {
        starPositions.push(
          (Math.random() - 0.5) * 20,
          (Math.random() - 0.5) * 20,
          (Math.random() - 0.5) * 20
        )
        starColors.push(1, 1, 1)
      }
      
      starGeometry.setAttribute('position', new THREE.Float32BufferAttribute(starPositions, 3))
      starGeometry.setAttribute('color', new THREE.Float32BufferAttribute(starColors, 3))
      
      const starMaterial = new THREE.PointsMaterial({
        size: 0.05,
        vertexColors: true,
        transparent: true,
        opacity: 0.8,
      })
      
      const stars = new THREE.Points(starGeometry, starMaterial)
      scene.add(stars)
      scene.add(streaks)

      camera.position.z = 5

      // Animation loop
      const animate = () => {
        animationId = requestAnimationFrame(animate)
        
        // Animate streaks
        streaks.children.forEach((streak: THREE.Object3D) => {
          if (streak.userData.speed) {
            streak.position.x += streak.userData.speed
            streak.position.y -= streak.userData.speed
            
            // Reset position when streak goes off screen
            if (streak.position.x > 10 || streak.position.y < -10) {
              streak.position.x = -10
              streak.position.y = 10
            }
          }
        })
        
        // Rotate stars slowly
        stars.rotation.y += 0.001
        
        renderer.render(scene, camera)
      }

      animate()

      // Handle resize
      const handleResize = () => {
        camera.aspect = window.innerWidth / window.innerHeight
        camera.updateProjectionMatrix()
        renderer.setSize(window.innerWidth, window.innerHeight)
      }

      window.addEventListener('resize', handleResize)

      return () => {
        window.removeEventListener('resize', handleResize)
        cancelAnimationFrame(animationId)
        renderer.dispose()
      }
    } catch (err) {
      console.warn('Three.js failed to initialize, falling back to CSS:', err)
      setError(err instanceof Error ? err.message : 'Three.js error')
      setUseCanvas(false)
    }
  }, [])

  if (!useCanvas || error) {
    // CSS fallback with animated lines
    return (
      <div className={`absolute inset-0 overflow-hidden ${className}`}>
        {/* CSS animated streaks */}
        <div className="absolute inset-0">
          {[...Array(8)].map((_, i) => (
            <div
              key={i}
              className="absolute w-px h-32 bg-gradient-to-b from-accent1/60 to-transparent animate-streak"
              style={{
                left: `${Math.random() * 100}%`,
                top: `${Math.random() * 100}%`,
                animationDelay: `${Math.random() * 8}s`,
                animationDuration: `${8 + Math.random() * 4}s`,
              }}
            />
          ))}
          
          {/* Star particles */}
          {[...Array(20)].map((_, i) => (
            <div
              key={`star-${i}`}
              className="absolute w-1 h-1 bg-white rounded-full animate-float opacity-60"
              style={{
                left: `${Math.random() * 100}%`,
                top: `${Math.random() * 100}%`,
                animationDelay: `${Math.random() * 6}s`,
                animationDuration: `${6 + Math.random() * 4}s`,
              }}
            />
          ))}
        </div>
      </div>
    )
  }

  return (
    <canvas
      ref={canvasRef}
      className={`absolute inset-0 w-full h-full ${className}`}
      style={{ zIndex: -1 }}
    />
  )
}

export default CanvasStreaks
